Lemma u32s_zero13 : u32s (map (Z_to_bv 64) (repeat 0 13)) = repeat (Z_to_bv 8 0) (Z.to_nat 52).
Proof.
ltac2:(KReplay.run1 (kr_t_RF_huf_rs_tail ()) [] "p;1p;2p;3g0000j10Tg000Uj19Tg0013j13Tg001Vj12Tg0026j28Tg002\j11Tg003Aj17Tg003_j14Tg004?j35Tg004^j26Tg0058R0#0#0#0#9R1#3R2#2g005],81%10#0#1#0#0#7#4552'6o"). Qed.

Section TL.
  Variables (sp gp tp : word) (F : bvmap 5 word) (fc : bv 32).
  (* [comment removed for export] *)
  Variables (x22 x23 x24 x25 x26 x27 : word).
  Variables (m : fmem) (HW RK NSP TLP iS : Z) (ws : list Z) (junk : list byte) (nsv tlv : word).
  Variable POST : machine_state -> Prop.
  Hypothesis HWS : 0 <= zlen ws <= 255.
  Hypothesis HWB : Forall (fun c => 0 <= c < 256) ws.
  Hypothesis HIS : 0 <= iS <= 128.
  Hypothesis HJK : zlen junk = 256 - zlen ws.
  Hypothesis HHW : 0 < HW /\ HW + 256 <= 2^64.
  Hypothesis HRK : 0 < RK /\ RK + 52 <= 2^64.
  Hypothesis HNT : 0 < NSP /\ NSP + 4 <= TLP /\ TLP + 4 <= 2^64.
  Hypothesis DHR : HW + 256 <= RK \/ RK + 52 <= HW.
  Hypothesis DHN : HW + 256 <= NSP \/ TLP + 4 <= HW.
  Hypothesis DRN : RK + 52 <= NSP \/ TLP + 4 <= RK.

  Notation WF := [(HW, HW + 256); (RK, RK + 52); (NSP, NSP + 4); (TLP, TLP + 4)].

  Lemma rs_tail_walk : forall m1 (jr : list byte) (x1 x5 x6 x7 x10 x11 x15 x16 x17 x19 x20 x21 x28 x29 x30 x31 : word),
    u8arr psegs m1 RK jr -> zlen jr = 52 ->
    u8arr psegs m1 HW (map (Z_to_bv 8) ws ++ junk) ->
    rw_cells psegs m1 NSP [C4 nsv] -> rw_cells psegs m1 TLP [C4 tlv] ->
    munch WF m m1 -> wmono psegs m m1 -> mem_inv psegs m1 ->
    (forall m2 a0v (y1 y5 y6 y7 y11 y12 y13 y14 y15 y16 y17 y18 y28 y29 y30 y31 : word),
       munch WF m m2 -> wmono psegs m m2 -> mem_inv psegs m2 ->
       rres HW RK NSP TLP (rs_tail ws (zlen ws) iS) m2 a0v ->
       evt psegs POST (MS (mkR y1 sp gp tp y5 y6 y7 (Z_to_bv 64 RK) (Z_to_bv 64 iS) (Z_to_bv 64 a0v) y11 y12 y13 y14 y15 y16
                               y17 y18 (Z_to_bv 64 TLP) (Z_to_bv 64 HW) (Z_to_bv 64 NSP) x22 x23 x24 x25 x26 x27 y28 y29
                               y30 y31)
                          F (Z_to_bv 64 0x1b84c) fc None m2 (seg_rom psegs))) ->
    evt psegs POST (MS (mkR x1 sp gp tp x5 x6 x7 (Z_to_bv 64 RK) (Z_to_bv 64 iS) x10 x11 (Z_to_bv 64 HW) (Z_to_bv 64 NSP)
                            (Z_to_bv 64 TLP) x15 x16 x17 (Z_to_bv 64 (zlen ws)) x19 x20 x21 x22 x23 x24 x25 x26 x27
                            x28 x29 x30 x31)
                       F (Z_to_bv 64 0x1b660) fc None m1 (seg_rom psegs)).
